import sys, json, time, hashlib
import redis

host, port, out = sys.argv[1], int(sys.argv[2]), sys.argv[3]
r = redis.Redis(host=host, port=port, protocol=2)

def digest(*parts):
    h = hashlib.sha256()
    for p in parts:
        if isinstance(p, bytes):
            h.update(p)
        elif isinstance(p, str):
            h.update(p.encode())
        else:
            h.update(repr(p).encode())
        h.update(b'\x00')
    return h.hexdigest()

inv = {"time_ms": int(time.time()*1000), "dbs": {}}
types = {}
for db in range(16):
    rc = redis.Redis(host=host, port=port, db=db, protocol=2)
    keys = sorted(b.decode('utf-8', 'surrogateescape') for b in rc.scan_iter(match='*', count=500))
    if not keys:
        continue
    dbd = {}
    for k in keys:
        t = rc.type(k).decode()
        pttl = rc.pttl(k)
        now = int(time.time()*1000)
        rec = {"type": t, "pttl": pttl, "expire_at": (now + pttl if pttl > 0 else None), "now": now}
        if t == 'string':
            v = rc.get(k)
            rec["digest"] = digest(v)
            rec["len"] = len(v) if v else 0
        elif t == 'list':
            vals = rc.lrange(k, 0, -1)
            rec["digest"] = digest(*vals); rec["len"] = len(vals)
        elif t == 'set':
            vals = sorted(rc.smembers(k))
            rec["digest"] = digest(*vals); rec["len"] = len(vals)
        elif t == 'zset':
            vals = rc.zrange(k, 0, -1, withscores=True)
            flat = []
            for m, s in vals:
                flat.append(m); flat.append(repr(s).encode())
            rec["digest"] = digest(*flat); rec["len"] = len(vals)
        elif t == 'hash':
            hv = rc.hgetall(k)
            flat = []
            for f in sorted(hv):
                flat.append(f); flat.append(hv[f])
            rec["digest"] = digest(*flat); rec["len"] = len(hv)
        elif t == 'stream':
            info = rc.xinfo_stream(k)
            groups = []
            for g in rc.xinfo_groups(k):
                g = {kk: vv for kk, vv in g.items()}
                cname = g['name']
                consumers = []
                for c in rc.xinfo_consumers(k, cname):
                    c = {kk: vv for kk, vv in c.items()}
                    consumers.append({"name": c['name'].decode('utf-8','surrogateescape'), "pending": c['pending']})
                consumers.sort(key=lambda x: x['name'])
                groups.append({
                    "name": cname.decode('utf-8','surrogateescape'),
                    "consumers": g['consumers'], "pending": g['pending'],
                    "last-delivered-id": g['last-delivered-id'].decode(),
                    "entries-read": g.get('entries-read'),
                    "consumer_list": consumers,
                })
            groups.sort(key=lambda x: x['name'])
            entries = rc.xrange(k, min='-', max='+')
            eflat = []
            for eid, fields in entries:
                eflat.append(eid); 
                for f in sorted(fields): eflat.append(f); eflat.append(fields[f])
            rec["digest"] = digest(*eflat)
            rec["stream"] = {
                "length": info[b'length'] if b'length' in info else info['length'],
                "last-generated-id": (info.get(b'last-generated-id') or info.get('last-generated-id')).decode(),
                "groups": groups,
            }
            rec["len"] = rec["stream"]["length"]
        else:
            rec["digest"] = None
        types[t] = types.get(t, 0) + 1
        dbd[k] = rec
    inv["dbs"][str(db)] = dbd
inv["types"] = types
with open(out, 'w') as f:
    json.dump(inv, f, ensure_ascii=False, sort_keys=True, indent=1)
print(f"keys={sum(len(v) for v in inv['dbs'].values())} types={inv['types']} dbs={list(inv['dbs'])}")
