import json, sys
a = json.load(open(sys.argv[1]))   # source
b = json.load(open(sys.argv[2]))   # target
errs, warns = [], []
tol = int(sys.argv[3]) if len(sys.argv) > 3 else 5000

def dbkeys(inv): return {db: set(d.keys()) for db, d in inv["dbs"].items()}
ak, bk = dbkeys(a), dbkeys(b)
for db in sorted(set(ak) | set(bk), key=int):
    A, B = ak.get(db, set()), bk.get(db, set())
    for k in sorted(A - B): errs.append(f"db{db} MISSING on target: {k}")
    for k in sorted(B - A): errs.append(f"db{db} EXTRA on target: {k}")
    for k in sorted(A & B):
        ra, rb = a["dbs"][db][k], b["dbs"][db][k]
        if ra["type"] != rb["type"]:
            errs.append(f"db{db} {k}: type {ra['type']} != {rb['type']}"); continue
        if ra.get("digest") != rb.get("digest"):
            errs.append(f"db{db} {k} ({ra['type']}): value digest mismatch")
        if ra.get("len") != rb.get("len"):
            errs.append(f"db{db} {k}: len {ra.get('len')} != {rb.get('len')}")
        # TTL
        ea, eb = ra.get("expire_at"), rb.get("expire_at")
        if (ea is None) != (eb is None):
            errs.append(f"db{db} {k}: TTL presence mismatch src={ra['pttl']} tgt={rb['pttl']}")
        elif ea is not None:
            d = abs(ea - eb)
            if d > tol:
                errs.append(f"db{db} {k}: expire_at differs by {d}ms (src pttl {ra['pttl']}, tgt {rb['pttl']})")
            elif d > 0:
                warns.append(f"db{db} {k}: expire_at delta {d}ms")
        # stream structure incl. consumer groups
        if ra["type"] == "stream" and ra.get("stream") != rb.get("stream"):
            errs.append(f"db{db} {k}: stream/groups mismatch\n  src={json.dumps(ra['stream'], sort_keys=True)}\n  tgt={json.dumps(rb['stream'], sort_keys=True)}")
if a.get("types") != b.get("types"):
    errs.append(f"type histogram mismatch: src={a.get('types')} tgt={b.get('types')}")
print(f"source keys={sum(len(v) for v in a['dbs'].values())} target keys={sum(len(v) for v in b['dbs'].values())}")
print(f"source types={a.get('types')}")
print(f"target types={b.get('types')}")
print(f"max expire_at delta in tolerated set: {max((abs(x['expire_at']-y['expire_at']) for db in a['dbs'] for x,y in [(a['dbs'][db][k], b['dbs'][db][k])] if db in b['dbs'] and k in b['dbs'][db] and x.get('expire_at') and y.get('expire_at')), default=0)} ms")
streams = sum(1 for db in a["dbs"] for k,v in a["dbs"][db].items() if v["type"]=="stream")
groups = sum(len(v.get("stream",{}).get("groups",[])) for db in a["dbs"] for v in a["dbs"][db].values() if v["type"]=="stream")
consumers = sum(len(g.get("consumer_list",[])) for db in a["dbs"] for v in a["dbs"][db].values() if v["type"]=="stream" for g in v.get("stream",{}).get("groups",[]))
print(f"streams={streams} groups={groups} consumers={consumers} (all structure-compared)")
if warns: print(f"({len(warns)} sub-tolerance TTL warnings, max {max(int(w.split('delta ')[1].split('ms')[0]) for w in warns)}ms)" if warns else "")
if errs:
    print(f"\n{len(errs)} ERRORS:"); [print("  " + e) for e in errs[:50]]; sys.exit(1)
print("\nOK: exact match (keys, types, values, TTLs, stream groups)")
